//     __ _____ _____ _____\n//  __|  |   __|     |   | |  JSON for Modern C++\n// |  |  |__   |  |  | | | |  version 3.12.0\n// |_____|_____|_____|_|___|  https://github.com/nlohmann/json\n//\n// SPDX-FileCopyrightText: 2013-2025 Niels Lohmann <https://nlohmann.me>\n// SPDX-License-Identifier: MIT\n\n#pragma once\n\n#include <cstddef> // size_t\n#include <stdexcept> // runtime_error\n\n#ifdef _WIN32\n    #include <windows.h>\n    #include <psapi.h>\n#else\n    #include <sys/resource.h>\n    #include <sys/sysinfo.h>\n#endif\n\nNLOHMANN_JSON_NAMESPACE_BEGIN\nnamespace detail\n{\n\n/**\n * @brief Memory monitoring utility class\n * \n * This class provides functionality to monitor current memory usage and\n * check if it exceeds a specified threshold.\n */\nclass memory_monitor\n{\npublic:\n    /**\n     * @brief Constructor\n     * \n     * @param absolute_threshold Absolute memory threshold in bytes (0 means no limit)\n     * @param relative_threshold Relative memory threshold as percentage of total system memory (0.0 to 1.0, 0.0 means no limit)\n     */\n    explicit memory_monitor(std::size_t absolute_threshold = 0, double relative_threshold = 0.0)\n        : m_absolute_threshold(absolute_threshold), m_relative_threshold(relative_threshold)\n    {\n        if (relative_threshold < 0.0 || relative_threshold > 1.0)\n        {\n            throw std::invalid_argument("relative_threshold must be between 0.0 and 1.0");\n        }\n        \n        m_total_system_memory = get_total_system_memory();\n    }\n    \n    /**\n     * @brief Get current memory usage of the process in bytes\n     * \n     * @return Current memory usage in bytes\n     */\n    std::size_t get_current_memory_usage() const;\n    \n    /**\n     * @brief Check if current memory usage exceeds the threshold\n     * \n     * @return True if memory usage exceeds threshold, false otherwise\n     */\n    bool is_memory_exceeded() const;\n    \n    /**\n     * @brief Set absolute memory threshold\n     * \n     * @param threshold Absolute memory threshold in bytes (0 means no limit)\n     */\n    void set_absolute_threshold(std::size_t threshold) noexcept\n    {\n        m_absolute_threshold = threshold;\n    }\n    \n    /**\n     * @brief Get absolute memory threshold\n     * \n     * @return Absolute memory threshold in bytes\n     */\n    std::size_t get_absolute_threshold() const noexcept\n    {\n        return m_absolute_threshold;\n    }\n    \n    /**\n     * @brief Set relative memory threshold\n     * \n     * @param threshold Relative memory threshold as percentage of total system memory (0.0 to 1.0)\n     * @throws std::invalid_argument if threshold is not in [0.0, 1.0]\n     */\n    void set_relative_threshold(double threshold)\n    {\n        if (threshold < 0.0 || threshold > 1.0)\n        {\n            throw std::invalid_argument("relative_threshold must be between 0.0 and 1.0");\n        }\n        m_relative_threshold = threshold;\n    }\n    \n    /**\n     * @brief Get relative memory threshold\n     * \n     * @return Relative memory threshold as percentage of total system memory\n     */\n    double get_relative_threshold() const noexcept\n    {\n        return m_relative_threshold;\n    }\n    \n    /**\n     * @brief Get total system memory in bytes\n     * \n     * @return Total system memory in bytes\n     */\n    std::size_t get_total_system_memory() const noexcept\n    {\n        return m_total_system_memory;\n    }\n    \nprivate:\n    /**\n     * @brief Get total system memory\n     * \n     * @return Total system memory in bytes\n     */\n    static std::size_t get_total_system_memory() noexcept;\n    \n    /// Absolute memory threshold in bytes (0 means no limit)\n    std::size_t m_absolute_threshold;\n    /// Relative memory threshold as percentage of total system memory (0.0 to 1.0)\n    double m_relative_threshold;\n    /// Total system memory in bytes\n    std::size_t m_total_system_memory;\n};\n\n// Implementation of get_current_memory_usage\ntemplate<typename = void>\nstd::size_t memory_monitor::get_current_memory_usage() const\n{\n#ifdef _WIN32\n    PROCESS_MEMORY_COUNTERS_EX pmc;\n    if (GetProcessMemoryInfo(GetCurrentProcess(), reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&pmc), sizeof(pmc)))\n    {\n        return pmc.PrivateUsage;\n    }\n    return 0;\n#else\n    struct rusage usage;\n    if (getrusage(RUSAGE_SELF, &usage) == 0)\n    {\n        return usage.ru_maxrss * 1024; // Convert from KB to bytes\n    }\n    return 0;\n#endif\n}\n\n// Implementation of is_memory_exceeded\ntemplate<typename = void>\nbool memory_monitor::is_memory_exceeded() const\n{\n    const std::size_t current_usage = get_current_memory_usage();\n    \n    // Check absolute threshold\n    if (m_absolute_threshold > 0 && current_usage > m_absolute_threshold)\n    {\n        return true;\n    }\n    \n    // Check relative threshold\n    if (m_relative_threshold > 0.0 && m_total_system_memory > 0)\n    {\n        const std::size_t relative_limit = static_cast<std::size_t>(m_total_system_memory * m_relative_threshold);\n        if (current_usage > relative_limit)\n        {\n            return true;\n        }\n    }\n    \n    return false;\n}\n\n// Implementation of get_total_system_memory\ntemplate<typename = void>\nstd::size_t memory_monitor::get_total_system_memory() const noexcept\n{\n#ifdef _WIN32\n    MEMORYSTATUSEX statex;\n    statex.dwLength = sizeof(statex);\n    if (GlobalMemoryStatusEx(&statex))\n    {\n        return statex.ullTotalPhys;\n    }\n    return 0;\n#else\n    struct sysinfo info;\n    if (sysinfo(&info) == 0)\n    {\n        return info.totalram * info.mem_unit;\n    }\n    return 0;\n#endif\n}\n\n} // namespace detail\nNLOHMANN_JSON_NAMESPACE_END\n